<script lang="ts">
  import { onMount } from 'svelte';
  type Evidence={title:string;url:string;locator:string;relationship:string;reuseStatus:string;verificationStatus:string;originalText:string|null;translation:string|null};
  type QueueItem={revisionId:string;mappingId:string;version:number;tradition:string;region:string;nakshatra:string;claim:string;interpretation:string;latestReview:string;publicationState:string;sources:Evidence[];botanicalCandidates:{scientificName:string;certainty:string;confidence:number;reviewStatus:string;evidence:Evidence[]}[]};
  let queue:QueueItem[]=$state([]);let message=$state('');let error=$state('');
  let source=$state({title:'',sourceType:'publication',author:'',publisher:'',publicationDate:'',url:'',bibliographicReference:'',language:'en',accessedOn:new Date().toISOString().slice(0,10),attributionRequirements:'',reuseStatus:'unknown'});
  let sourceId=$state('');let evidence=$state({locator:'',language:'en',originalText:'',evidenceNotes:''});let evidenceId=$state('');
  let mapping=$state({mappingId:'',tradition:'nakshatra-tree-association',regionCode:'',nakshatra:'',claim:'',interpretation:'',evidenceId:''});
  let botanicalJSON=$state('');let botanicalCandidateIds:string[]=$state([]);
  async function call(path:string,body?:unknown){const response=await fetch(path,{method:body?'POST':'GET',headers:{'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});if(!response.ok){const b=await response.json().catch(()=>({}));throw new Error(b.error??`Request failed (${response.status})`)}return response.status===204?null:response.json()}
  async function refresh(){try{queue=await call('/internal/v1/review/queue');error=''}catch(e){error=e instanceof Error?e.message:'Could not load queue.'}}
  async function createSource(){try{const b=await call('/internal/v1/sources',{...source,publicationDate:source.publicationDate||null});sourceId=b.id;message=`Source saved as ${sourceId}. It is unverified until reviewed.`;await refresh()}catch(e){error=e instanceof Error?e.message:'Could not save source.'}}
  async function createEvidence(){try{const b=await call(`/internal/v1/sources/${sourceId}/evidence`,{...evidence,originalText:evidence.originalText||null,translationRights:'not_applicable'});evidenceId=b.id;message=`Evidence saved as ${evidenceId}.`; }catch(e){error=e instanceof Error?e.message:'Could not save evidence.'}}
  async function verifySource(decision:string){try{await call(`/internal/v1/sources/${sourceId}/review`,{decision,notes:'Reviewed in local workflow'});message=`Source marked ${decision}.`;await refresh()}catch(e){error=e instanceof Error?e.message:'Could not review source.'}}
  async function createMapping(){try{const candidates=botanicalJSON.trim()?JSON.parse(botanicalJSON):[];const b=await call('/internal/v1/mappings',{...mapping,mappingId:mapping.mappingId||undefined,evidence:mapping.evidenceId.split(',').map((id)=>({id:id.trim(),relationship:'supports'})).filter((x)=>x.id),botanicalCandidates:candidates});message=`Immutable revision ${b.version} created. Keep ID ${b.mappingId} to submit a later revision.`;mapping.mappingId=b.mappingId;botanicalCandidateIds=b.botanicalCandidateIds??[];await refresh()}catch(e){error=e instanceof Error?e.message:'Could not create mapping or parse botanical candidate JSON.'}}
  async function reviewBotanical(candidateId:string,decision:string){try{await call(`/internal/v1/botanical-candidates/${candidateId}/review`,{decision,notes:'Reviewed in local workflow'});message=`Botanical identification ${decision}.`;error=''}catch(e){error=e instanceof Error?e.message:'Botanical review failed; restart the local API with ADMIN_REVIEWER_ROLE=botanical or admin.'}}
  async function review(item:QueueItem,decision:string){try{await call(`/internal/v1/review/${item.revisionId}`,{decision,notes:'Reviewed in local workflow'});message=`Revision ${item.version} ${decision}.`;await refresh()}catch(e){error=e instanceof Error?e.message:'Could not record review.'}}
  async function publish(item:QueueItem,action:string){try{await call(`/internal/v1/publications/${item.revisionId}`,{action,reason:'Local review workflow'});message=`Revision ${item.version} ${action}.`;await refresh()}catch(e){error=e instanceof Error?e.message:'Publication gate rejected this revision.'}}
  onMount(refresh);
</script>

<p class="eyebrow">INTERNAL · LOCAL DEVELOPMENT ONLY</p><h1>Knowledge review</h1><p class="notice">API authorization checks loopback access and explicit local configuration. Do not expose this interface or enable review access outside your machine.</p>
{#if error}<p role="alert" class="error">{error}</p>{/if}{#if message}<p class="message" aria-live="polite">{message}</p>{/if}
<section class="card"><h2>1. Register a source</h2><p>Enter bibliographic details and rights. A reviewer must verify it before a mapping can be published.</p>
  <div class="grid"><label>Title<input bind:value={source.title} required /></label><label>Type<input bind:value={source.sourceType} /></label><label>Author<input bind:value={source.author} /></label><label>Publisher<input bind:value={source.publisher} /></label><label>URL<input bind:value={source.url} /></label><label>Bibliographic reference<input bind:value={source.bibliographicReference} /></label><label>Language<input bind:value={source.language} /></label><label>Accessed on<input type="date" bind:value={source.accessedOn} /></label><label>Attribution terms<input bind:value={source.attributionRequirements} /></label><label>Reuse status<select bind:value={source.reuseStatus}><option value="unknown">Unknown</option><option value="citation_only">Citation only</option><option value="permitted">Permitted</option><option value="restricted">Restricted</option></select></label></div>
  <button onclick={createSource}>Save source</button>{#if sourceId}<code>{sourceId}</code><button class="secondary" onclick={()=>verifySource('approved')}>Approve source verification</button><button class="secondary" onclick={()=>verifySource('rejected')}>Reject source</button>{/if}
</section>
{#if sourceId}<section class="card"><h2>2. Add a source evidence locator</h2><p>Leave passage text blank unless the source rights allow reproduction.</p><div class="grid"><label>Page, section, URL fragment, or locator<input bind:value={evidence.locator} /></label><label>Language<input bind:value={evidence.language} /></label><label class="wide">Original excerpt (only if permitted)<textarea bind:value={evidence.originalText}></textarea></label><label class="wide">Evidence notes<textarea bind:value={evidence.evidenceNotes}></textarea></label></div><button onclick={createEvidence}>Save evidence</button>{#if evidenceId}<code>{evidenceId}</code>{/if}</section>{/if}
{#if evidenceId}<section class="card"><h2>3. Submit a cultural mapping revision</h2><p>Every submission creates a new immutable revision. A later revision must be reviewed and published separately.</p><div class="grid"><label>Existing mapping ID (blank for new)<input bind:value={mapping.mappingId} /></label><label>Tradition slug<input bind:value={mapping.tradition} /></label><label>Region code (blank for general)<input bind:value={mapping.regionCode} /></label><label>Nakshatra<input bind:value={mapping.nakshatra} placeholder="Ashwini" /></label><label class="wide">Original cultural claim<textarea bind:value={mapping.claim}></textarea></label><label class="wide">Everroot interpretation (optional, distinct)<textarea bind:value={mapping.interpretation}></textarea></label><label class="wide">Evidence IDs, comma separated<input bind:value={mapping.evidenceId} /></label><label class="wide">Botanical candidates JSON (optional; each needs separate evidence)<textarea bind:value={botanicalJSON} placeholder="Paste botanical candidate JSON with its evidence UUIDs"></textarea></label></div><button onclick={createMapping}>Create revision</button>{#each botanicalCandidateIds as candidateId}<div class="candidate"><code>{candidateId}</code><button class="secondary" onclick={()=>reviewBotanical(candidateId,'approved')}>Approve botanical identification</button><button class="danger" onclick={()=>reviewBotanical(candidateId,'rejected')}>Reject botanical identification</button></div>{/each}<small>Botanical review requires the API role ADMIN_REVIEWER_ROLE=botanical or admin.</small></section>{/if}
<section class="card"><div class="row"><h2>Mapping review & publication</h2><button class="secondary" onclick={refresh}>Refresh</button></div>{#if queue.length===0}<p>No mapping revisions have been submitted.</p>{:else}{#each queue as item}<article class="queue"><p><strong>{item.tradition}</strong>{item.region?` · ${item.region}`:''} — {item.nakshatra} · revision {item.version}</p><p><strong>Latest review:</strong> {item.latestReview} · <strong>Publication:</strong> {item.publicationState}</p><blockquote>{item.claim}</blockquote>{#if item.interpretation}<p><strong>Everroot interpretation:</strong> {item.interpretation}</p>{/if}<small>Revision {item.revisionId}</small><h3>Cultural evidence</h3>{#if item.sources.length}{#each item.sources as source}<div class="evidence">{#if source.url}<a href={source.url} target="_blank" rel="noreferrer">{source.title}</a>{:else}{source.title}{/if} · {source.locator} · {source.relationship} · rights: {source.reuseStatus} · source: {source.verificationStatus}{#if source.originalText}<blockquote>{source.originalText}</blockquote>{/if}</div>{/each}{:else}<p>No evidence attached.</p>{/if}{#if item.botanicalCandidates.length}<h3>Botanical candidates (separate review)</h3><ul>{#each item.botanicalCandidates as candidate}<li><i>{candidate.scientificName}</i> — {candidate.certainty}, confidence {candidate.confidence} · {candidate.reviewStatus}{#if candidate.evidence.length}<ul>{#each candidate.evidence as source}<li>{source.title} · {source.locator} · {source.relationship}</li>{/each}</ul>{/if}</li>{/each}</ul>{/if}<div class="actions"><button onclick={()=>review(item,'approved')}>Approve claim</button><button class="secondary" onclick={()=>review(item,'changes_requested')}>Request changes</button><button class="danger" onclick={()=>review(item,'rejected')}>Reject</button>{#if item.publicationState==='published'}<button class="secondary" onclick={()=>publish(item,'unpublished')}>Unpublish</button><button class="danger" onclick={()=>publish(item,'withdrawn')}>Withdraw</button>{:else if item.latestReview==='approved'&&item.publicationState!=='withdrawn'}<button class="secondary" onclick={()=>publish(item,'published')}>Publish this revision</button>{/if}</div></article>{/each}{/if}</section>

<style>
  .eyebrow{font-size:.76rem;letter-spacing:.13em;font-weight:750;color:#537866}h1{font-size:2.7rem;line-height:1.08;letter-spacing:-.04em;margin:.6rem 0 1rem;color:#173c2e}.notice{background:#fff6dc;border-left:4px solid #d4a533;padding:.8rem 1rem}.card{background:#fff;padding:1.3rem 1.5rem;margin:1.2rem 0;border:1px solid #e1e2d8;border-radius:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:.8rem 1rem;margin:1rem 0}label{display:grid;gap:.35rem;font-weight:600}input,select,textarea{font:inherit;padding:.6rem .7rem;border:1px solid #c8d0c8;border-radius:8px;color:#23332b;background:white}textarea{min-height:70px}.wide{grid-column:1/-1}button{background:#27664e;color:#fff;border:0;border-radius:8px;padding:.62rem .85rem;margin:.25rem .4rem .25rem 0;font:inherit;font-weight:650;cursor:pointer}.secondary{background:#e8eee8;color:#234537}.danger{background:#f4e5e2;color:#7b2f29}.message{color:#245c42}.error{color:#a22d26}.row,.actions{display:flex;align-items:center;gap:.3rem;flex-wrap:wrap}.row{justify-content:space-between}.queue{padding:1rem 0;border-top:1px solid #e3e5df}blockquote{margin:.5rem 0;padding-left:1rem;border-left:3px solid #b9cbbc}.queue small,code{color:#68756c;overflow-wrap:anywhere}@media(max-width:650px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style>
